description:
Write the two filters of lesson 4.02 that keep driver logging cheap: the level-and-keyword check, and a token-bucket rate limiter for messages from hot paths.

```cpp
bool enabled(int level, std::uint64_t keywords, int sessionLevel, std::uint64_t sessionMask);

class RateLimiter
{
public:
    RateLimiter(int perSecond, int burst);
    std::string log(std::int64_t nowMs, const std::string& message);
};
```

- `enabled`: levels are numbers where smaller is more important (1 critical ... 5 verbose); an event is enabled when its level is at most `sessionLevel` and it has no keywords, or shares at least one keyword bit with `sessionMask`.
- `RateLimiter`: a bucket holds up to `burst` tokens and starts full; it refills at `perSecond` tokens per second, continuously. Each message costs one token. If a token is available, `log` returns the message, prefixed by `"(<n> suppressed) "` if `n` messages were suppressed since the last one that got through; otherwise it counts the message as suppressed and returns `""`. Use integer arithmetic: keep the bucket in thousandths of a token (a message costs 1000), and add `elapsedMs * perSecond` thousandths per elapsed millisecond. Time never goes backwards in the tests.

starter.solution.cpp:
#include <cstdint>
#include <string>

bool enabled(int level, std::uint64_t keywords, int sessionLevel, std::uint64_t sessionMask) { return false; }

class RateLimiter
{
public:
    RateLimiter(int perSecond, int burst) {}
    std::string log(std::int64_t nowMs, const std::string& message) { return ""; }
};

solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <string>

bool enabled(int level, std::uint64_t keywords, int sessionLevel, std::uint64_t sessionMask)
{
    return level <= sessionLevel && (keywords == 0 || (keywords & sessionMask) != 0);
}

class RateLimiter
{
public:
    RateLimiter(int perSecond, int burst) : m_rate{ perSecond }, m_cap{ static_cast<std::int64_t>(burst) * 1000 }, m_tokens{ m_cap } {}

    std::string log(std::int64_t nowMs, const std::string& message)
    {
        if (m_started) m_tokens = std::min(m_cap, m_tokens + (nowMs - m_last) * m_rate);
        m_started = true;
        m_last = nowMs;
        if (m_tokens < 1000) { ++m_suppressed; return ""; }
        m_tokens -= 1000;
        std::string out{ m_suppressed ? "(" + std::to_string(m_suppressed) + " suppressed) " + message : message };
        m_suppressed = 0;
        return out;
    }

private:
    std::int64_t m_rate, m_cap, m_tokens;
    std::int64_t m_last{ 0 };
    bool m_started{ false };
    int m_suppressed{ 0 };
};

unitTests:
TEST("levels and keywords") {
    CHECK(enabled(2, 0x1, 4, 0x3)); CHECK(!enabled(5, 0x1, 4, 0x3)); CHECK(!enabled(2, 0x4, 4, 0x3)); CHECK(enabled(1, 0, 4, 0)); CHECK(enabled(4, 0x6, 4, 0x2));
}
TEST("bursts, then a steady rate") {
    RateLimiter r{ 2, 3 };
    CHECK_EQ(r.log(0, "a"), std::string("a")); CHECK_EQ(r.log(0, "b"), std::string("b")); CHECK_EQ(r.log(0, "c"), std::string("c"));
    CHECK_EQ(r.log(0, "d"), std::string("")); CHECK_EQ(r.log(100, "e"), std::string(""));
    CHECK_EQ(r.log(500, "f"), std::string("(2 suppressed) f")); CHECK_EQ(r.log(600, "g"), std::string(""));
    CHECK_EQ(r.log(1000, "h"), std::string("(1 suppressed) h"));
}
TEST("the bucket never overfills") {
    RateLimiter r{ 10, 2 }; CHECK_EQ(r.log(0, "x"), std::string("x")); CHECK_EQ(r.log(60000, "y"), std::string("y")); CHECK_EQ(r.log(60000, "z"), std::string("z")); CHECK_EQ(r.log(60000, "w"), std::string(""));
}

